// MAIRFM Car Mode — minimal Wave Mode for iPhone landscape.
(()=>{
'use strict';
if(window.MAIRCarModePrototype)return;
const $=id=>document.getElementById(id);
let overlay=null,isOpen=false,volumeTimer=null,wakeLock=null,wakeLockRetryTimer=null;
function playbackState(){try{return window.JFMPlaybackState?.get?.()||{}}catch{return{}}}
function currentTrack(){const s=playbackState();return{title:String($('title')?.textContent||s.title||s.name||'MAIRFM').trim(),artist:String($('artist')?.textContent||s.artist||'').trim(),isPlaying:typeof s.isPlaying==='boolean'?s.isPlaying:!!s.expectedLive}}
function wakeLockSupported(){return!!window.navigator?.wakeLock?.request}
function clearWakeLockRetry(){if(wakeLockRetryTimer){clearTimeout(wakeLockRetryTimer);wakeLockRetryTimer=null}}
function scheduleWakeLockRetry(){clearWakeLockRetry();if(!isOpen||document.visibilityState!=='visible'||!wakeLockSupported())return;wakeLockRetryTimer=setTimeout(()=>{wakeLockRetryTimer=null;void requestWakeLock()},1500)}
async function requestWakeLock(){if(!isOpen||document.visibilityState!=='visible'||!wakeLockSupported())return false;if(wakeLock&&!wakeLock.released)return true;clearWakeLockRetry();try{const lock=await window.navigator.wakeLock.request('screen');if(!isOpen||document.visibilityState!=='visible'){try{await lock.release()}catch{}return false}wakeLock=lock;lock.addEventListener('release',()=>{if(wakeLock===lock)wakeLock=null;if(isOpen&&document.visibilityState==='visible')scheduleWakeLockRetry()},{once:true});return true}catch{wakeLock=null;return false}}
async function releaseWakeLock(){clearWakeLockRetry();const lock=wakeLock;wakeLock=null;if(lock&&!lock.released){try{await lock.release()}catch{}}}
function waveMarkup(){return `<svg viewBox="0 0 900 260" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="mairCarWaveGradient" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#5930a9" stop-opacity=".08"/><stop offset=".5" stop-color="#b865ff"/><stop offset="1" stop-color="#53269a" stop-opacity=".08"/></linearGradient></defs><path d="M-20 145 C75 118 105 185 185 147 S310 65 394 136 S506 202 596 137 S725 82 920 148"/><path d="M-20 159 C94 210 137 84 230 151 S351 205 438 144 S563 75 650 143 S795 207 920 119"/><path d="M-20 119 C83 64 138 201 242 130 S367 78 458 146 S573 201 672 128 S806 73 920 151"/></svg>`}
function ensure(){if(overlay)return overlay;overlay=document.createElement('div');overlay.id='mairCarWaveOverlay';overlay.className='mair-car-wave-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','MAIRFM Car Mode');overlay.innerHTML=`<div class="mair-car-shell"><div class="mair-car-brand"><strong>MAIR<span>FM</span></strong></div><button type="button" class="mair-car-close" data-car-close aria-label="Car Mode sluiten">×</button><main class="mair-car-main"><div class="mair-car-wave-art">${waveMarkup()}</div><div class="mair-car-topline"><span class="mair-car-onair">ON AIR</span></div><section class="mair-car-track"><h1 id="mairCarTitle">MAIRFM</h1><div class="artist" id="mairCarArtist"></div><div class="mair-car-transport"><button type="button" class="mair-car-skip" data-car-transport="prev" aria-label="Vorige">◀︎</button><button type="button" class="mair-car-play" data-car-transport="play" aria-label="Play of pauze"><span id="mairCarPlayIcon">Ⅱ</span></button><button type="button" class="mair-car-skip" data-car-transport="next" aria-label="Volgende">▶︎</button></div></section><label class="mair-car-volume"><span>🔊</span><input id="mairCarVolume" type="range" min="0" max="100" value="55" aria-label="Volume"><output id="mairCarVolumeValue">55</output></label></main></div>`;document.body.appendChild(overlay);overlay.addEventListener('click',e=>{if(e.target.closest('[data-car-close]')){setOpen(false);return}const t=e.target.closest('[data-car-transport]');if(t)forwardTransport(t.dataset.carTransport)});const volume=$('mairCarVolume');volume?.addEventListener('input',()=>{const n=Math.max(0,Math.min(100,Number(volume.value)||0));if($('mairCarVolumeValue'))$('mairCarVolumeValue').value=String(n);clearTimeout(volumeTimer);volumeTimer=setTimeout(()=>setVolume(n),80)});volume?.addEventListener('change',()=>setVolume(Number(volume.value)||0));return overlay}
function forwardTransport(action){const id=action==='play'?'play':action==='prev'?'prev':action==='next'?'next':'';const target=id?$(id):null;if(target){target.click();setTimeout(render,100);return true}if(action==='play'&&typeof window.JFMPlayback?.playPause==='function'){Promise.resolve(window.JFMPlayback.playPause()).finally(()=>setTimeout(render,100));return true}return false}
async function setVolume(percent){const value=Math.max(0,Math.min(100,Math.round(Number(percent)||0))),deviceId=String(window.JFMSpotifySDK?.deviceId||localStorage.getItem('jfm_spotify_device_id')||'').trim();let localOk=false;try{if(window.jfmSpotifyPlayer?.setVolume){await window.jfmSpotifyPlayer.setVolume(value/100);localOk=true}}catch{}try{if(typeof window.api==='function'){const suffix=deviceId?`&device_id=${encodeURIComponent(deviceId)}`:'';await window.api(`/me/player/volume?volume_percent=${value}${suffix}`,{method:'PUT'});localOk=true}}catch{}try{localStorage.setItem('mair_volume_percent',String(value));window.dispatchEvent(new CustomEvent('mair:volume-change',{detail:{percent:value,source:'car-mode'}}))}catch{}return localOk}
function render(){ensure();const t=currentTrack();if($('mairCarTitle'))$('mairCarTitle').textContent=t.title||'MAIRFM';if($('mairCarArtist'))$('mairCarArtist').textContent=t.artist||'';if($('mairCarPlayIcon'))$('mairCarPlayIcon').textContent=t.isPlaying?'Ⅱ':'▶︎'}
function setOpen(value){ensure();isOpen=!!value;overlay.classList.toggle('is-open',isOpen);document.body.classList.toggle('mair-car-mode-open',isOpen);if(isOpen){render();document.body.dataset.mairCarMode='1';void requestWakeLock()}else{delete document.body.dataset.mairCarMode;void releaseWakeLock()}try{window.dispatchEvent(new CustomEvent('mair:car-mode',{detail:{open:isOpen}}))}catch{}}
function onKey(e){if(isOpen&&e.key==='Escape')setOpen(false)};document.addEventListener('keydown',onKey);document.addEventListener('visibilitychange',()=>{if(!isOpen)return;if(document.visibilityState==='visible')void requestWakeLock();else void releaseWakeLock()});window.addEventListener('pageshow',()=>{if(isOpen)void requestWakeLock()});window.addEventListener('pagehide',()=>{void releaseWakeLock()});['jfm:trackchange','jfm:playback-state','mair:channelchange'].forEach(name=>window.addEventListener(name,()=>{if(isOpen)render()}));
window.MAIRCarModePrototype={version:'wave-minimal-volume-wakelock-2026-08-29',open:()=>setOpen(true),close:()=>setOpen(false),toggle:()=>setOpen(!isOpen),render,setVolume,setQueue:()=>{},setDJBreak:()=>{},setMix:()=>{},status:()=>({open:isOpen,wakeLockSupported:wakeLockSupported(),wakeLockActive:!!(wakeLock&&!wakeLock.released)})};
})();